"""Compact derived audit snapshot; no candles, account databases or raw order-book samples."""
import argparse,json,html,hashlib
from pathlib import Path
from datetime import datetime,timezone
p=argparse.ArgumentParser();p.add_argument('--source',required=True);args=p.parse_args();src=Path(args.source);repo=Path(__file__).resolve().parent.parent;out=repo/'experimentos/donchian-defesa';out.mkdir(parents=True,exist_ok=True)
d=json.loads((src/'web/data/donchian-market-defense.json').read_text());a=d['diagnosis']
def compact(r):return {**{k:v for k,v in r.items()if k not in ['trades','curve','benchmark']},'benchmark':{k:v for k,v in r['benchmark'].items()if k!='curve'}}
snapshot={**d,'diagnosis':{**{k:v for k,v in a.items()if k not in ['curve','benchmark']},'benchmark':{k:v for k,v in a['benchmark'].items()if k!='curve'}},'rows':[compact(r)for r in d['rows']],'snapshotAt':datetime.now(timezone.utc).isoformat(),'testsPassed':291,'codeManifestSHA256':hashlib.sha256((repo/'app/source-manifest.json').read_bytes()).hexdigest()};(out/'snapshot.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2)+'\n')
